import{_ as s,o as a,c as t,a2 as i}from"./chunks/framework.BvlN9b-o.js";const u=JSON.parse('{"title":"Reuse Identity and Account Transactions","description":"","frontmatter":{"docLocale":"en","counterpart":"/tutorials/registration","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"en/tutorials/registration.md","filePath":"en/tutorials/registration.md"}'),n={name:"en/tutorials/registration.md"};function r(o,e,d,c,l,p){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="reuse-identity-and-account-transactions" tabindex="-1">Reuse Identity and Account Transactions <a class="header-anchor" href="#reuse-identity-and-account-transactions" aria-label="Permalink to &quot;Reuse Identity and Account Transactions&quot;">​</a></h1><p>Goal: use Core registration and credentials without reimplementing passwords, User or Membership in a business module. Start the API and PostgreSQL from the <a href="./../getting-started/quickstart">quickstart</a>. Run commands from the repository root.</p><h2 id="connect-identity-endpoints" tabindex="-1">Connect Identity Endpoints <a class="header-anchor" href="#connect-identity-endpoints" aria-label="Permalink to &quot;Connect Identity Endpoints&quot;">​</a></h2><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/lib.rs" target="_blank" rel="noreferrer">Core Router</a> composes <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/identity/mod.rs" target="_blank" rel="noreferrer">Identity</a>: <code>POST /api/v1/auth/register</code>, <code>POST /api/v1/auth/login</code> and <code>GET /api/v1/auth/session</code>. Registration accepts <code>email</code>, <code>password</code> and optional <code>display_name</code>; the server determines the role.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:18000/api/v1/auth/session</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-backend.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> registration</span></span></code></pre></div><p>Anonymous requests return 401 and request_id. Public registration checks create accounts through the real Router, obtain Cookies and query identity, verifying the first Owner and later Member. Complete requests are in the <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/tests/registration.rs" target="_blank" rel="noreferrer">registration HTTP tests</a>, DTOs in the <a href="./../reference/api">API reference</a>. Your Handler integration follows on the <a href="./sessions">next page</a>.</p><h2 id="transactions-and-commit-boundaries" tabindex="-1">Transactions and Commit Boundaries <a class="header-anchor" href="#transactions-and-commit-boundaries" aria-label="Permalink to &quot;Transactions and Commit Boundaries&quot;">​</a></h2><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/migrations/0002_identity.sql" target="_blank" rel="noreferrer">Identity migration</a> stores accounts, credentials, memberships, sessions and audit. Registration creates User, Credential, Membership and Audit in one transaction; failure rolls everything back. Admission uses <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/organization/mod.rs" target="_blank" rel="noreferrer">Organization</a>&#39;s public interface:</p><div class="language-rust vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">pub</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> fn</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> enroll</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    connection</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &amp;mut</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> PgConnection</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    user_id</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &amp;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">str</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Result</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MemberRole</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, sqlx</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Error</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;;</span></span></code></pre></div><p>This is an interface excerpt. The singleton Organization row serializes first Owner initialization; requests cannot select Owner. Each deployment serves one Organization and business modules do not add another tenant layer. See the <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/docs/adr/0001-single-organization-deployment.md" target="_blank" rel="noreferrer">ADR</a>.</p><p>Session issuance follows the account commit. <code>auth.session_unavailable</code> means the account exists and login provides recovery. Repeated registration cannot overwrite passwords, roles or inactive status.</p><h2 id="password-and-secret-boundaries" tabindex="-1">Password and Secret Boundaries <a class="header-anchor" href="#password-and-secret-boundaries" aria-label="Permalink to &quot;Password and Secret Boundaries&quot;">​</a></h2><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/crates/app/src/modules/identity/crypto.rs" target="_blank" rel="noreferrer">password implementation</a> uses Argon2id with random salt. Blocking computation has 4 concurrent slots; saturation returns retryable 503. Passwords are 12–128 characters. Email is trimmed and unique in lowercase, without folding <code>+tag</code> or dots; concurrent duplicates allow one success.</p><p>A Session is a 256-bit random secret with only SHA-256 stored. HTTPS uses <code>__Host-saas_session</code> with Secure, HttpOnly, SameSite=Lax, Path=/ and no Domain; loopback HTTP is for development. Keep secrets out of business JSON, logs and browser storage.</p><p>Registration requires trusted <code>APP_ORIGIN</code>, never inferred from request Host. JSON is limited to 16 KiB and a 3-second read; the account transaction has 3 seconds and separate Session issuance has 2 seconds. Responses use no-store. A lost success response does not mean account creation failed; do not automatically repeat registration POST.</p><h2 id="verify-and-adapt" tabindex="-1">Verify and Adapt <a class="header-anchor" href="#verify-and-adapt" aria-label="Permalink to &quot;Verify and Adapt&quot;">​</a></h2><p>Checks cover duplicate email, concurrent first Owner, Audit rollback, Cookies, credential storage and origin rejection. Audit failure must leave no account; a committed account with failed Session issuance must later be able to log in.</p><p>Reference User IDs from business tables and check current membership. For customer-profile initialization, decide which facts must commit together and use public capabilities; keep profile rules in your module. Continue with <a href="./sessions">Session, Origin and CSRF</a>, then business transactions and idempotency.</p><p>Complete reference: <a href="./personal-documents">business transactions and idempotency</a>.</p><hr><p>Source version：<code>e87f840d6dfc</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e87f840d6dfcfb1436042f731d0c0d7d5cadc9b2/docs/tutorials/02-registration.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,21)])])}const k=s(n,[["render",r]]);export{u as __pageData,k as default};
